// ----- nx/NxBodyExtractor.cs -----
// NX layer: reads a solid body's faces, edges, features and the part's attributes
// into the neutral BodyModel. This is the only place that touches NX geometry.
namespace LaserDxf.Nx
{
    using System;
    using System.Collections.Generic;
    using NXOpen;
    using NXOpen.UF;
    using LaserDxf.Core;

    public sealed class NxBodyExtractor
    {
        readonly UFSession uf;
        readonly List<string> log;

        /// <summary>Chord tolerance (mm) when sampling edges that are not lines or arcs.</summary>
        public double ChordTol = 0.01;

        public readonly Dictionary<Tag, int> FaceIdByTag = new Dictionary<Tag, int>();
        public readonly Dictionary<Tag, int> EdgeIdByTag = new Dictionary<Tag, int>();
        public readonly Dictionary<int, Face> FaceById = new Dictionary<int, Face>();

        int vertexMismatches;

        public NxBodyExtractor(UFSession uf, List<string> log)
        {
            this.uf = uf;
            this.log = log;
        }

        public BodyModel Extract(Body body, Part part)
        {
            var m = new BodyModel();
            m.PartName = NxUtil.PartLabel(part);
            m.Units = part.PartUnits.ToString();

            Face[] faces = body.GetFaces();
            Edge[] edges = body.GetEdges();
            foreach (Face f in faces)
            {
                int id = FaceIdByTag.Count + 1;
                FaceIdByTag[f.Tag] = id;
                FaceById[id] = f;
            }
            foreach (Edge e in edges) EdgeIdByTag[e.Tag] = EdgeIdByTag.Count + 1;

            foreach (Edge e in edges) m.Edges.Add(ExtractEdge(e));

            foreach (Face f in faces)
            {
                var tf = new TopoFace
                {
                    Id = FaceIdByTag[f.Tag],
                    NxType = f.SolidFaceType.ToString(),
                    Kind = MapFace(f.SolidFaceType)
                };
                foreach (Edge e in f.GetEdges())
                {
                    int eid;
                    if (EdgeIdByTag.TryGetValue(e.Tag, out eid)) tf.EdgeIds.Add(eid);
                }
                m.Faces.Add(tf);
            }

            if (vertexMismatches > 0)
                log.Add("WARNING: " + vertexMismatches + " edge(s) whose sampled end points do not match their NX vertices. Please send me the debug file.");

            ExtractFeatures(body, part, m);
            NxAttributes.Read(part, m, log);
            return m;
        }

        static FaceKind MapFace(Face.FaceType t)
        {
            if (t == Face.FaceType.Planar) return FaceKind.Planar;
            if (t == Face.FaceType.Cylindrical) return FaceKind.Cylindrical;
            if (t == Face.FaceType.Conical) return FaceKind.Conical;
            return FaceKind.Other;
        }

        Vec3 Eval(Edge e, double param, out double radiusOfCurvature)
        {
            double[] p = new double[3];
            double[] tangent = new double[3];
            double[] pNorm = new double[3];
            double[] bNorm = new double[3];
            double torsion;
            // UF_MODL_ask_curve_props: parameter is normalised 0..1 over the edge.
            uf.Modl.AskCurveProps(e.Tag, param, p, tangent, pNorm, bNorm, out torsion, out radiusOfCurvature);
            return new Vec3(p[0], p[1], p[2]);
        }

        Vec3 Eval(Edge e, double param)
        {
            double r;
            return Eval(e, param, out r);
        }

        TopoEdge ExtractEdge(Edge e)
        {
            var te = new TopoEdge { Id = EdgeIdByTag[e.Tag], NxType = e.SolidEdgeType.ToString() };
            foreach (Face f in e.GetFaces())
            {
                int fid;
                if (FaceIdByTag.TryGetValue(f.Tag, out fid)) te.FaceIds.Add(fid);
            }
            try { te.Length = e.GetLength(); }
            catch (Exception ex) { log.Add("Edge " + te.Id + ": GetLength failed: " + ex.Message); }

            Edge.EdgeType et = e.SolidEdgeType;
            if (et == Edge.EdgeType.Linear)
            {
                te.Kind = EdgeKind.Line;
                te.Points.Add(Eval(e, 0.0));
                te.Points.Add(Eval(e, 1.0));
            }
            else if (et == Edge.EdgeType.Circular)
            {
                te.Kind = EdgeKind.Circular;
                for (int i = 0; i <= 4; i++) te.Points.Add(Eval(e, i / 4.0));
                Vec3 c, axis;
                double r;
                if (GeomUtil.CircleFrom3Points(te.Points[0], te.Points[1], te.Points[2], out c, out r, out axis))
                {
                    te.HasCircle = true;
                    te.Center = c;
                    te.Radius = r;
                    te.Axis = axis;
                    double rc;
                    Eval(e, 0.5, out rc);
                    if (Math.Abs(rc - r) > 1e-4)
                        log.Add("Edge " + te.Id + ": 3-point radius " + Fmt.N(r, 5) + " differs from NX curvature radius " + Fmt.N(rc, 5));
                }
                else log.Add("Edge " + te.Id + ": circular edge but the sample points are collinear?");
            }
            else
            {
                te.Kind = EdgeKind.Other;
                Edge edge = e;
                te.Points = Sampler.Sample(delegate (double s) { return Eval(edge, s); }, ChordTol, 8, 12);
            }

            CheckVertices(e, te);
            return te;
        }

        void CheckVertices(Edge e, TopoEdge te)
        {
            try
            {
                Point3d v1, v2;
                e.GetVertices(out v1, out v2);
                Vec3 a = new Vec3(v1.X, v1.Y, v1.Z);
                Vec3 b = new Vec3(v2.X, v2.Y, v2.Z);
                const double tol = 1e-3;
                bool startOk = te.Start.DistanceTo(a) < tol || te.Start.DistanceTo(b) < tol;
                bool endOk = te.End.DistanceTo(a) < tol || te.End.DistanceTo(b) < tol;
                if (!startOk || !endOk)
                {
                    vertexMismatches++;
                    if (vertexMismatches <= 5)
                        log.Add("Edge " + te.Id + " (" + te.NxType + "): vertices " + a + " " + b + " but sampled ends " + te.Start + " " + te.End);
                }
            }
            catch (Exception ex)
            {
                log.Add("Edge " + te.Id + ": GetVertices failed: " + ex.Message);
            }
        }

        void ExtractFeatures(Body body, Part part, BodyModel m)
        {
            NXOpen.Features.Feature[] feats;
            try { feats = body.GetFeatures(); }
            catch (Exception ex)
            {
                log.Add("Body.GetFeatures failed: " + ex.Message);
                return;
            }

            int id = 1;
            foreach (NXOpen.Features.Feature feat in feats)
            {
                var fi = new FeatureInfo { Id = id++, ClassName = feat.GetType().Name };
                try { fi.Name = feat.GetFeatureName(); } catch { fi.Name = feat.JournalIdentifier; }
                try { fi.FeatureType = feat.FeatureType; } catch { }

                var bf = feat as NXOpen.Features.BodyFeature;
                if (bf != null)
                {
                    try
                    {
                        foreach (Face f in bf.GetFaces())
                        {
                            int fid;
                            if (FaceIdByTag.TryGetValue(f.Tag, out fid)) fi.FaceIds.Add(fid);
                        }
                    }
                    catch (Exception ex) { log.Add("Feature " + fi.Name + ": GetFaces failed: " + ex.Message); }
                }

                if (fi.ClassName == "HolePackage")
                    NxReflect.ReadHoleBuilder(part, feat, fi.Props, log);

                m.Features.Add(fi);
            }
        }
    }
}

// ----- nx/NxSupport.cs -----
// NX layer helpers: attributes, reflection-based dumps, output files, messages.
// Calls whose exact NX Open signature I could not verify are made through
// reflection, so a wrong guess shows up as a logged warning, not a compile error.
namespace LaserDxf.Nx
{
    using System;
    using System.Collections.Generic;
    using System.IO;
    using System.Reflection;
    using System.Text;
    using NXOpen;
    using LaserDxf.Core;

    public static class NxUtil
    {
        public static string PartLabel(Part part)
        {
            string s = null;
            try { s = part.Leaf; } catch { }
            if (string.IsNullOrEmpty(s)) try { s = part.Name; } catch { }
            return s ?? "unknown";
        }

        public static string SafeFileName(string s)
        {
            var sb = new StringBuilder();
            foreach (char c in s)
                sb.Append(Array.IndexOf(Path.GetInvalidFileNameChars(), c) >= 0 ? '_' : c);
            return sb.ToString().Trim();
        }

        /// <summary>Creates the folder, falling back to %TEMP%\LaserDxf if that fails.</summary>
        public static string EnsureFolder(string folder, List<string> log)
        {
            try
            {
                Directory.CreateDirectory(folder);
                return folder;
            }
            catch (Exception ex)
            {
                string fb = Path.Combine(Path.GetTempPath(), "LaserDxf");
                Directory.CreateDirectory(fb);
                log.Add("WARNING: cannot create " + folder + " (" + ex.Message + "), using " + fb);
                return fb;
            }
        }

        public static void WriteText(string path, string text)
        {
            File.WriteAllText(path, text, new UTF8Encoding(false));
        }

        public static void Message(string title, NXMessageBox.DialogType type, string message)
        {
            UI.GetUI().NXMessageBox.Show(title, type, message);
        }
    }

    public static class NxAttributes
    {
        static readonly string[] AliasMembers = { "Alias", "TitleAlias", "AliasName" };
        static readonly string[] UnsetMembers = { "Unset", "IsUnset" };

        /// <summary>Reads every part attribute with its category. Uses reflection on
        /// NXObject.AttributeInformation so differing member names between NX versions don't break the build.</summary>
        public static void Read(Part part, BodyModel m, List<string> log)
        {
            NXObject.AttributeInformation[] infos;
            try { infos = part.GetUserAttributes(); }
            catch (Exception ex)
            {
                log.Add("GetUserAttributes failed: " + ex.Message);
                return;
            }

            if (infos.Length > 0)
                log.Add("AttributeInformation members: " + NxReflect.MemberNames(infos[0]));

            foreach (NXObject.AttributeInformation info in infos)
            {
                object boxed = info;
                var a = new AttributeEntry
                {
                    Title = info.Title ?? "",
                    Category = info.Category ?? "",
                    Type = info.Type.ToString()
                };
                foreach (string n in AliasMembers)
                {
                    object v = NxReflect.Member(boxed, n);
                    if (v != null) { a.Alias = v.ToString(); break; }
                }
                foreach (string n in UnsetMembers)
                {
                    object v = NxReflect.Member(boxed, n);
                    if (v is bool) { a.IsSet = !(bool)v; break; }
                }
                object val = NxReflect.Member(boxed, a.Type + "Value");
                if (val == null) val = NxReflect.Member(boxed, "StringValue");
                a.Value = val == null ? "" : Convert.ToString(val, Fmt.Inv);
                m.Attributes.Add(a);
            }
        }
    }

    public static class NxReflect
    {
        public static object Member(object obj, string name)
        {
            if (obj == null) return null;
            Type t = obj.GetType();
            try
            {
                FieldInfo f = t.GetField(name, BindingFlags.Public | BindingFlags.Instance);
                if (f != null) return f.GetValue(obj);
                PropertyInfo p = t.GetProperty(name, BindingFlags.Public | BindingFlags.Instance);
                if (p != null && p.CanRead && p.GetIndexParameters().Length == 0) return p.GetValue(obj, null);
            }
            catch { }
            return null;
        }

        public static string MemberNames(object obj)
        {
            var names = new List<string>();
            Type t = obj.GetType();
            foreach (FieldInfo f in t.GetFields(BindingFlags.Public | BindingFlags.Instance)) names.Add(f.Name);
            foreach (PropertyInfo p in t.GetProperties(BindingFlags.Public | BindingFlags.Instance)) names.Add(p.Name);
            return string.Join(", ", names.ToArray());
        }

        static string Describe(object v)
        {
            if (v == null) return "null";
            if (v is string) return "\"" + v + "\"";
            if (v is double) return Fmt.R((double)v);
            if (v is Enum || v.GetType().IsPrimitive) return Convert.ToString(v, Fmt.Inv);
            object rhs = Member(v, "RightHandSide");
            if (rhs != null) return "expr \"" + rhs + "\" = " + Convert.ToString(Member(v, "Value"), Fmt.Inv);
            var arr = v as Array;
            if (arr != null) return v.GetType().Name + "[" + arr.Length + "]";
            return v.GetType().Name;
        }

        static readonly string[] SkipProps = { "Tag", "Prototype", "OwningPart", "OwningComponent", "IsOccurrence", "JournalIdentifier", "IsBlanked" };

        public static void ReadProps(object obj, string prefix, List<KeyValuePair<string, string>> props, int depth)
        {
            if (obj == null || props.Count > 400) return;
            PropertyInfo[] ps = obj.GetType().GetProperties(BindingFlags.Public | BindingFlags.Instance);
            Array.Sort(ps, delegate (PropertyInfo x, PropertyInfo y) { return string.CompareOrdinal(x.Name, y.Name); });
            foreach (PropertyInfo p in ps)
            {
                if (!p.CanRead || p.GetIndexParameters().Length > 0 || Array.IndexOf(SkipProps, p.Name) >= 0) continue;
                object v;
                try { v = p.GetValue(obj, null); }
                catch (Exception ex)
                {
                    Exception inner = ex.InnerException ?? ex;
                    props.Add(new KeyValuePair<string, string>(prefix + p.Name, "<error: " + inner.Message + ">"));
                    continue;
                }
                props.Add(new KeyValuePair<string, string>(prefix + p.Name, Describe(v)));
                if (v != null && depth > 0 && !(v is string) && !(v is Enum) && !v.GetType().IsPrimitive && Member(v, "RightHandSide") == null)
                {
                    string tn = v.GetType().Name;
                    if (tn.EndsWith("Builder") || tn.EndsWith("Data") || tn.EndsWith("Settings"))
                        ReadProps(v, prefix + p.Name + ".", props, depth - 1);
                }
            }
        }

        /// <summary>Opens a HolePackageBuilder on the feature (read-only, never committed) and records its properties.</summary>
        public static void ReadHoleBuilder(Part part, NXOpen.Features.Feature feat, List<KeyValuePair<string, string>> props, List<string> log)
        {
            object coll = part.Features;
            MethodInfo create = null;
            foreach (MethodInfo mi in coll.GetType().GetMethods())
            {
                if (mi.Name == "CreateHolePackageBuilder" && mi.GetParameters().Length == 1) { create = mi; break; }
            }
            if (create == null)
            {
                log.Add("FeatureCollection.CreateHolePackageBuilder not found - hole feature data unavailable.");
                return;
            }
            object builder = null;
            try
            {
                builder = create.Invoke(coll, new object[] { feat });
                ReadProps(builder, "", props, 1);
            }
            catch (Exception ex)
            {
                Exception inner = ex.InnerException ?? ex;
                log.Add("Reading hole feature " + feat.JournalIdentifier + " failed: " + inner.Message);
            }
            finally
            {
                if (builder != null)
                {
                    try { builder.GetType().GetMethod("Destroy", Type.EmptyTypes).Invoke(builder, null); }
                    catch (Exception ex) { log.Add("Builder.Destroy failed: " + ex.Message); }
                }
            }
        }

        /// <summary>Path of the running journal, if this NX version exposes Session.ExecutingJournal.</summary>
        public static string ExecutingJournal(Session s)
        {
            object v = Member(s, "ExecutingJournal");
            return v == null ? null : v.ToString();
        }
    }
}

// ----- nx/ProbeCommand.cs -----
// Step 1: select a plate face (or body) and dump what the journal sees.
// Writes a summary to the listing window, plus a full text dump and a JSON
// model of the body to the debug folder.
namespace LaserDxf.Nx
{
    using System;
    using System.Collections.Generic;
    using System.IO;
    using NXOpen;
    using NXOpen.UF;
    using LaserDxf.Core;

    public static class ProbeCommand
    {
        public const string Version = "probe 1.0 (step 1)";
        const string Title = "Laser DXF";
        const string DebugFolder = @"C:\Laser DXF\_debug";

        public static void Run()
        {
            Session s = Session.GetSession();
            ListingWindow lw = s.ListingWindow;
            lw.Open();
            var log = new List<string>();
            try
            {
                RunInner(s, lw, log);
            }
            catch (PlateException ex)
            {
                lw.WriteLine("ABORTED: " + ex.Message);
                NxUtil.Message(Title, NXMessageBox.DialogType.Error, ex.Message);
            }
            catch (Exception ex)
            {
                lw.WriteLine("ERROR: " + ex.GetType().Name + ": " + ex.Message);
                lw.WriteLine(ex.StackTrace ?? "");
                foreach (string l in log) lw.WriteLine("  log: " + l);
                NxUtil.Message(Title, NXMessageBox.DialogType.Error, "Unexpected error:\n" + ex.Message + "\n\nDetails are in the listing window.");
            }
        }

        static void RunInner(Session s, ListingWindow lw, List<string> log)
        {
            UFSession uf = UFSession.GetUFSession();
            UI ui = UI.GetUI();

            if (s.Parts.Work == null) throw new PlateException("Open the plate part first.");

            Selection.MaskTriple[] mask =
            {
                new Selection.MaskTriple(UFConstants.UF_solid_type, 0, UFConstants.UF_UI_SEL_FEATURE_ANY_FACE),
                new Selection.MaskTriple(UFConstants.UF_solid_type, 0, UFConstants.UF_UI_SEL_FEATURE_BODY)
            };
            TaggedObject picked;
            Point3d cursor;
            Selection.Response resp = ui.SelectionManager.SelectTaggedObject(
                "Select the plate face to view from (or the plate body)", "Laser DXF - select plate",
                Selection.SelectionScope.AnyInAssembly, Selection.SelectionAction.ClearAndEnableSpecific,
                false, false, mask, out picked, out cursor);
            if (resp != Selection.Response.ObjectSelected && resp != Selection.Response.ObjectSelectedByName) return;

            Face face = picked as Face;
            Body body = picked as Body;
            string note;

            // Work on the part itself, not an assembly occurrence: coordinates are then the part's own.
            if (face != null && face.IsOccurrence)
            {
                face = (Face)face.Prototype;
                log.Add("Selection was an assembly occurrence; using the component part's face.");
            }
            if (body != null && body.IsOccurrence)
            {
                body = (Body)body.Prototype;
                log.Add("Selection was an assembly occurrence; using the component part's body.");
            }
            if (face != null)
            {
                if (face.SolidFaceType != Face.FaceType.Planar)
                    throw new PlateException("The selected face is not planar (it is " + face.SolidFaceType + "). Select the flat top or bottom face of the plate.");
                body = face.GetBody();
            }
            if (body == null) throw new PlateException("Nothing usable was selected.");
            if (!body.IsSolidBody) throw new PlateException("The selected body is not a solid body.");

            Part part = body.OwningPart as Part;
            if (part == null) throw new PlateException("Could not find the part that owns the selected body.");

            var opt = new AnalysisOptions();
            var ex = new NxBodyExtractor(uf, log);
            BodyModel m = ex.Extract(body, part);

            int faceId;
            if (face != null)
            {
                faceId = ex.FaceIdByTag[face.Tag];
                note = "selected directly";
            }
            else
            {
                faceId = PlateAnalyzer.PickPlateFace(m, opt, Vec3.UnitZ, log);
                note = "picked automatically from the body";
            }

            FaceAnalysis a = PlateAnalyzer.Analyze(m, faceId, opt);

            // ---------- output ----------
            string stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
            string folder = NxUtil.EnsureFolder(DebugFolder, log);
            string baseName = NxUtil.SafeFileName(m.PartName) + "_" + stamp;
            string dumpPath = Path.Combine(folder, baseName + "_probe.txt");
            string jsonPath = Path.Combine(folder, baseName + "_body.json");

            var head = new List<string>();
            head.Add("=== Laser DXF " + Version + " ===   " + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));
            head.Add("NX part      : Leaf=\"" + SafeGet(delegate { return part.Leaf; }) + "\"  Name=\"" + SafeGet(delegate { return part.Name; }) +
                     "\"  FullPath=\"" + SafeGet(delegate { return part.FullPath; }) + "\"");
            head.Add("Journal path : " + (NxReflect.ExecutingJournal(s) ?? "(Session.ExecutingJournal not available)"));
            head.Add("Body         : " + m.Faces.Count + " faces, " + m.Edges.Count + " edges, " + m.Features.Count + " features, " + m.Attributes.Count + " attributes");

            List<string> summary = ProbeReport.Summary(m, a, note);
            var tail = new List<string>();
            if (a.Warnings.Count + log.Count > 0)
            {
                tail.Add("");
                tail.Add("Notes / warnings:");
                foreach (string w in a.Warnings) tail.Add("  WARNING: " + w);
                foreach (string l in log) tail.Add("  " + l);
            }

            var listing = new List<string>(head);
            listing.AddRange(summary);
            listing.Add("");
            int holeFeats = 0;
            foreach (var f in m.Features) if (f.ClassName == "HolePackage") holeFeats++;
            listing.Add("Hole features : " + holeFeats + "   (full properties are in the debug file)");
            listing.AddRange(tail);
            listing.Add("");

            var dump = new List<string>(listing);
            dump.AddRange(ProbeReport.FaceEdges(m, a));
            dump.Add("");
            dump.AddRange(ProbeReport.Features(m, true));
            dump.Add("");
            dump.AddRange(ProbeReport.Attributes(m));

            JObj json = m.ToJson();
            json.Add("selectedFaceId", (double)faceId);

            string written;
            try
            {
                NxUtil.WriteText(dumpPath, ProbeReport.Join(dump));
                NxUtil.WriteText(jsonPath, Json.Write(json));
                written = "Debug files  : " + dumpPath + "\n               " + jsonPath;
            }
            catch (Exception wex)
            {
                written = "Could not write debug files: " + wex.Message;
            }

            foreach (string l in listing) lw.WriteLine(l);
            lw.WriteLine("Part attributes: see the debug file (" + m.Attributes.Count + " found)");
            lw.WriteLine(written);
        }

        delegate string StringGetter();

        static string SafeGet(StringGetter g)
        {
            try { return g() ?? ""; }
            catch (Exception ex) { return "<" + ex.Message + ">"; }
        }
    }
}

// ----- core/BodyModel.cs -----
// Neutral description of a solid body's topology and geometry.
// The NX layer fills this in; everything downstream works on it alone.
// It can also be saved to JSON so real parts can be replayed in tests.
namespace LaserDxf.Core
{
    using System;
    using System.Collections.Generic;

    public enum FaceKind { Planar, Cylindrical, Conical, Other }

    public enum EdgeKind { Line, Circular, Other }

    public sealed class TopoEdge
    {
        public int Id;
        public EdgeKind Kind;
        public string NxType = "";
        public List<int> FaceIds = new List<int>();

        /// <summary>Sample points from start to end. Lines: 2 points. Circular: 5 points at
        /// t = 0, .25, .5, .75, 1. Other: adaptive samples within the chord tolerance.</summary>
        public List<Vec3> Points = new List<Vec3>();

        public bool HasCircle;
        public Vec3 Center;
        public double Radius;
        public Vec3 Axis;
        public double Length;

        public Vec3 Start { get { return Points[0]; } }
        public Vec3 End { get { return Points[Points.Count - 1]; } }

        public bool IsClosed(double tol) { return Start.DistanceTo(End) <= tol; }
    }

    public sealed class TopoFace
    {
        public int Id;
        public FaceKind Kind;
        public string NxType = "";
        public List<int> EdgeIds = new List<int>();
    }

    public sealed class FeatureInfo
    {
        public int Id;
        public string Name = "";
        public string FeatureType = "";
        public string ClassName = "";
        public List<int> FaceIds = new List<int>();
        public List<KeyValuePair<string, string>> Props = new List<KeyValuePair<string, string>>();

        public string Prop(string key)
        {
            foreach (var kv in Props) if (kv.Key == key) return kv.Value;
            return null;
        }
    }

    public sealed class AttributeEntry
    {
        public string Category = "";
        public string Title = "";
        public string Alias = "";
        public string Value = "";
        public string Type = "";
        public bool IsSet = true;
    }

    public sealed class BodyModel
    {
        public string PartName = "";
        public string Units = "Millimeters";
        public List<TopoFace> Faces = new List<TopoFace>();
        public List<TopoEdge> Edges = new List<TopoEdge>();
        public List<FeatureInfo> Features = new List<FeatureInfo>();
        public List<AttributeEntry> Attributes = new List<AttributeEntry>();

        Dictionary<int, TopoFace> faceIndex;
        Dictionary<int, TopoEdge> edgeIndex;

        public TopoFace Face(int id)
        {
            if (faceIndex == null || faceIndex.Count != Faces.Count)
            {
                faceIndex = new Dictionary<int, TopoFace>();
                foreach (var f in Faces) faceIndex[f.Id] = f;
            }
            return faceIndex[id];
        }

        public TopoEdge Edge(int id)
        {
            if (edgeIndex == null || edgeIndex.Count != Edges.Count)
            {
                edgeIndex = new Dictionary<int, TopoEdge>();
                foreach (var e in Edges) edgeIndex[e.Id] = e;
            }
            return edgeIndex[id];
        }

        public IEnumerable<Vec3> AllPoints()
        {
            foreach (var e in Edges)
                foreach (var p in e.Points)
                    yield return p;
        }

        // ---------------- JSON round trip ----------------

        static List<object> V(Vec3 v) { return new List<object> { v.X, v.Y, v.Z }; }

        static Vec3 ToVec(object o)
        {
            var l = (List<object>)o;
            return new Vec3((double)l[0], (double)l[1], (double)l[2]);
        }

        static List<object> Ints(List<int> ids)
        {
            var l = new List<object>();
            foreach (int i in ids) l.Add((double)i);
            return l;
        }

        static List<int> ToInts(object o)
        {
            var r = new List<int>();
            var l = o as List<object>;
            if (l != null) foreach (object x in l) r.Add((int)(double)x);
            return r;
        }

        public JObj ToJson()
        {
            var faces = new List<object>();
            foreach (var f in Faces)
                faces.Add(new JObj().Add("id", (double)f.Id).Add("kind", f.Kind.ToString()).Add("nxType", f.NxType).Add("edges", Ints(f.EdgeIds)));

            var edges = new List<object>();
            foreach (var e in Edges)
            {
                var pts = new List<object>();
                foreach (var p in e.Points) pts.Add(V(p));
                var o = new JObj().Add("id", (double)e.Id).Add("kind", e.Kind.ToString()).Add("nxType", e.NxType)
                    .Add("faces", Ints(e.FaceIds)).Add("length", e.Length).Add("points", pts);
                if (e.HasCircle) o.Add("center", V(e.Center)).Add("radius", e.Radius).Add("axis", V(e.Axis));
                edges.Add(o);
            }

            var feats = new List<object>();
            foreach (var f in Features)
            {
                var props = new JObj();
                foreach (var kv in f.Props) props.Add(kv.Key, kv.Value);
                feats.Add(new JObj().Add("id", (double)f.Id).Add("name", f.Name).Add("featureType", f.FeatureType)
                    .Add("className", f.ClassName).Add("faces", Ints(f.FaceIds)).Add("props", props));
            }

            var attrs = new List<object>();
            foreach (var a in Attributes)
                attrs.Add(new JObj().Add("category", a.Category).Add("title", a.Title).Add("alias", a.Alias)
                    .Add("value", a.Value).Add("type", a.Type).Add("isSet", a.IsSet));

            return new JObj().Add("format", "laserdxf-body-1").Add("partName", PartName).Add("units", Units)
                .Add("faces", faces).Add("edges", edges).Add("features", feats).Add("attributes", attrs);
        }

        public static BodyModel FromJson(JObj o)
        {
            var m = new BodyModel();
            m.PartName = o.Str("partName", "");
            m.Units = o.Str("units", "Millimeters");
            foreach (JObj f in o.Arr("faces"))
            {
                m.Faces.Add(new TopoFace
                {
                    Id = (int)f.Num("id", 0),
                    Kind = (FaceKind)Enum.Parse(typeof(FaceKind), f.Str("kind", "Other")),
                    NxType = f.Str("nxType", ""),
                    EdgeIds = ToInts(f.Get("edges"))
                });
            }
            foreach (JObj e in o.Arr("edges"))
            {
                var te = new TopoEdge
                {
                    Id = (int)e.Num("id", 0),
                    Kind = (EdgeKind)Enum.Parse(typeof(EdgeKind), e.Str("kind", "Other")),
                    NxType = e.Str("nxType", ""),
                    FaceIds = ToInts(e.Get("faces")),
                    Length = e.Num("length", 0)
                };
                foreach (object p in e.Arr("points")) te.Points.Add(ToVec(p));
                if (e.Has("center"))
                {
                    te.HasCircle = true;
                    te.Center = ToVec(e.Get("center"));
                    te.Radius = e.Num("radius", 0);
                    te.Axis = ToVec(e.Get("axis"));
                }
                m.Edges.Add(te);
            }
            var feats = o.Arr("features");
            if (feats != null)
            {
                foreach (JObj f in feats)
                {
                    var fi = new FeatureInfo
                    {
                        Id = (int)f.Num("id", 0),
                        Name = f.Str("name", ""),
                        FeatureType = f.Str("featureType", ""),
                        ClassName = f.Str("className", ""),
                        FaceIds = ToInts(f.Get("faces"))
                    };
                    var props = f.Obj("props");
                    if (props != null) foreach (var kv in props.Items) fi.Props.Add(new KeyValuePair<string, string>(kv.Key, Convert.ToString(kv.Value, Fmt.Inv)));
                    m.Features.Add(fi);
                }
            }
            var attrs = o.Arr("attributes");
            if (attrs != null)
            {
                foreach (JObj a in attrs)
                {
                    m.Attributes.Add(new AttributeEntry
                    {
                        Category = a.Str("category", ""),
                        Title = a.Str("title", ""),
                        Alias = a.Str("alias", ""),
                        Value = a.Str("value", ""),
                        Type = a.Str("type", ""),
                        IsSet = a.Bool("isSet", true)
                    });
                }
            }
            return m;
        }
    }
}

// ----- core/Geom.cs -----
// Pure geometry: vectors, plate coordinate frame, small numeric helpers.
// No NX dependencies - compiled and unit-tested outside NX.
namespace LaserDxf.Core
{
    using System;
    using System.Collections.Generic;
    using System.Globalization;

    public struct Vec3
    {
        public double X, Y, Z;

        public Vec3(double x, double y, double z) { X = x; Y = y; Z = z; }

        public static readonly Vec3 Zero = new Vec3(0, 0, 0);
        public static readonly Vec3 UnitX = new Vec3(1, 0, 0);
        public static readonly Vec3 UnitY = new Vec3(0, 1, 0);
        public static readonly Vec3 UnitZ = new Vec3(0, 0, 1);

        public static Vec3 operator +(Vec3 a, Vec3 b) { return new Vec3(a.X + b.X, a.Y + b.Y, a.Z + b.Z); }
        public static Vec3 operator -(Vec3 a, Vec3 b) { return new Vec3(a.X - b.X, a.Y - b.Y, a.Z - b.Z); }
        public static Vec3 operator -(Vec3 a) { return new Vec3(-a.X, -a.Y, -a.Z); }
        public static Vec3 operator *(Vec3 a, double s) { return new Vec3(a.X * s, a.Y * s, a.Z * s); }
        public static Vec3 operator *(double s, Vec3 a) { return new Vec3(a.X * s, a.Y * s, a.Z * s); }
        public static Vec3 operator /(Vec3 a, double s) { return new Vec3(a.X / s, a.Y / s, a.Z / s); }

        public double Dot(Vec3 b) { return X * b.X + Y * b.Y + Z * b.Z; }
        public Vec3 Cross(Vec3 b) { return new Vec3(Y * b.Z - Z * b.Y, Z * b.X - X * b.Z, X * b.Y - Y * b.X); }
        public double Length { get { return Math.Sqrt(X * X + Y * Y + Z * Z); } }
        public double DistanceTo(Vec3 b) { return (this - b).Length; }

        public Vec3 Normalized()
        {
            double l = Length;
            return l > 1e-300 ? this / l : this;
        }

        public override string ToString()
        {
            return "(" + Fmt.N(X) + ", " + Fmt.N(Y) + ", " + Fmt.N(Z) + ")";
        }
    }

    public struct Vec2
    {
        public double X, Y;

        public Vec2(double x, double y) { X = x; Y = y; }

        public static Vec2 operator +(Vec2 a, Vec2 b) { return new Vec2(a.X + b.X, a.Y + b.Y); }
        public static Vec2 operator -(Vec2 a, Vec2 b) { return new Vec2(a.X - b.X, a.Y - b.Y); }
        public static Vec2 operator *(Vec2 a, double s) { return new Vec2(a.X * s, a.Y * s); }

        public double Length { get { return Math.Sqrt(X * X + Y * Y); } }
        public double DistanceTo(Vec2 b) { return (this - b).Length; }

        public override string ToString()
        {
            return "(" + Fmt.N(X) + ", " + Fmt.N(Y) + ")";
        }
    }

    /// <summary>
    /// Right-handed frame on the selected face. Z is the outward face normal,
    /// so looking down -Z shows the plate exactly as seen from the selected side
    /// (never mirrored).
    /// </summary>
    public sealed class PlateFrame
    {
        public Vec3 Origin, XAxis, YAxis, ZAxis;

        public Vec2 ToLocal(Vec3 p)
        {
            Vec3 d = p - Origin;
            return new Vec2(d.Dot(XAxis), d.Dot(YAxis));
        }

        /// <summary>Signed height above the face plane (negative = into the material).</summary>
        public double Height(Vec3 p) { return (p - Origin).Dot(ZAxis); }

        public double Handedness { get { return XAxis.Cross(YAxis).Dot(ZAxis); } }
    }

    public struct Bounds2
    {
        public double MinX, MinY, MaxX, MaxY;

        public static Bounds2 Empty
        {
            get
            {
                Bounds2 b;
                b.MinX = b.MinY = double.MaxValue;
                b.MaxX = b.MaxY = double.MinValue;
                return b;
            }
        }

        public void Add(Vec2 p)
        {
            if (p.X < MinX) MinX = p.X;
            if (p.Y < MinY) MinY = p.Y;
            if (p.X > MaxX) MaxX = p.X;
            if (p.Y > MaxY) MaxY = p.Y;
        }

        public double Width { get { return MaxX - MinX; } }
        public double Height { get { return MaxY - MinY; } }
        public bool IsEmpty { get { return MaxX < MinX; } }
    }

    public static class GeomUtil
    {
        /// <summary>Newell's method: returns 2 * area * unit normal of a closed polygon.</summary>
        public static Vec3 NewellNormal(IList<Vec3> pts)
        {
            double x = 0, y = 0, z = 0;
            int n = pts.Count;
            for (int i = 0; i < n; i++)
            {
                Vec3 a = pts[i];
                Vec3 b = pts[(i + 1) % n];
                x += (a.Y - b.Y) * (a.Z + b.Z);
                y += (a.Z - b.Z) * (a.X + b.X);
                z += (a.X - b.X) * (a.Y + b.Y);
            }
            return new Vec3(x, y, z);
        }

        /// <summary>Signed area of a closed 2D polygon (CCW positive).</summary>
        public static double SignedArea(IList<Vec2> pts)
        {
            double a = 0;
            int n = pts.Count;
            for (int i = 0; i < n; i++)
            {
                Vec2 p = pts[i];
                Vec2 q = pts[(i + 1) % n];
                a += p.X * q.Y - q.X * p.Y;
            }
            return a * 0.5;
        }

        /// <summary>Circle through three 3D points. Returns false if they are collinear.</summary>
        public static bool CircleFrom3Points(Vec3 a, Vec3 b, Vec3 c, out Vec3 center, out double radius, out Vec3 normal)
        {
            Vec3 u = a - c;
            Vec3 v = b - c;
            Vec3 w = u.Cross(v);
            double w2 = w.Dot(w);
            double scale = Math.Max(u.Dot(u), v.Dot(v));
            if (scale <= 0 || w2 <= 1e-18 * scale * scale)
            {
                center = Vec3.Zero;
                radius = 0;
                normal = Vec3.Zero;
                return false;
            }
            Vec3 num = (v * u.Dot(u) - u * v.Dot(v)).Cross(w);
            center = c + num / (2 * w2);
            radius = center.DistanceTo(a);
            normal = w.Normalized();
            return true;
        }

        /// <summary>Distance from p to the infinite line through a and b.</summary>
        public static double DistanceToLine(Vec3 p, Vec3 a, Vec3 b)
        {
            Vec3 d = b - a;
            double len = d.Length;
            if (len < 1e-12) return p.DistanceTo(a);
            return (p - a).Cross(d).Length / len;
        }

        /// <summary>Projects v onto the plane with unit normal n.</summary>
        public static Vec3 ProjectOntoPlane(Vec3 v, Vec3 n)
        {
            return v - n * v.Dot(n);
        }
    }

    /// <summary>Invariant-culture number formatting (Windows locale must never leak into files).</summary>
    public static class Fmt
    {
        public static readonly CultureInfo Inv = CultureInfo.InvariantCulture;

        public static string N(double v) { return N(v, 4); }

        public static string N(double v, int decimals)
        {
            if (double.IsNaN(v)) return "NaN";
            double r = Math.Round(v, decimals);
            if (r == 0) r = 0; // drop negative zero
            return r.ToString("0." + new string('#', decimals), Inv);
        }

        public static string R(double v)
        {
            return v.ToString("R", Inv);
        }
    }
}

namespace LaserDxf.Core
{
    using System.Collections.Generic;

    /// <summary>Insertion-ordered int set. (HashSet lives in System.Core, which an NX
    /// journal may not reference, so the shared code sticks to mscorlib + System.)</summary>
    public sealed class IntSet
    {
        readonly Dictionary<int, bool> map = new Dictionary<int, bool>();
        public readonly List<int> Items = new List<int>();

        public bool Add(int v)
        {
            if (map.ContainsKey(v)) return false;
            map[v] = true;
            Items.Add(v);
            return true;
        }

        public bool Contains(int v) { return map.ContainsKey(v); }
        public int Count { get { return Items.Count; } }
    }
}

// ----- core/Json.cs -----
// Minimal JSON reader/writer. NX journals can only reference a fixed set of
// assemblies, so we don't rely on System.Web / System.Runtime.Serialization.
namespace LaserDxf.Core
{
    using System;
    using System.Collections.Generic;
    using System.Globalization;
    using System.Text;

    /// <summary>JSON object that keeps key order (so dumps stay readable and diffable).</summary>
    public sealed class JObj
    {
        public readonly List<KeyValuePair<string, object>> Items = new List<KeyValuePair<string, object>>();

        public JObj Add(string key, object value)
        {
            Items.Add(new KeyValuePair<string, object>(key, value));
            return this;
        }

        public bool Has(string key)
        {
            foreach (var kv in Items) if (kv.Key == key) return true;
            return false;
        }

        public object Get(string key)
        {
            foreach (var kv in Items) if (kv.Key == key) return kv.Value;
            return null;
        }

        public string Str(string key, string def)
        {
            object v = Get(key);
            if (v == null) return def;
            if (v is string) return (string)v;
            if (v is double) return ((double)v).ToString("R", CultureInfo.InvariantCulture);
            if (v is bool) return (bool)v ? "true" : "false";
            return def;
        }

        public double Num(string key, double def)
        {
            object v = Get(key);
            if (v is double) return (double)v;
            double d;
            if (v is string && double.TryParse((string)v, NumberStyles.Float, CultureInfo.InvariantCulture, out d)) return d;
            return def;
        }

        public bool Bool(string key, bool def)
        {
            object v = Get(key);
            if (v is bool) return (bool)v;
            return def;
        }

        public JObj Obj(string key) { return Get(key) as JObj; }
        public List<object> Arr(string key) { return Get(key) as List<object>; }
    }

    public static class Json
    {
        // ---------------- writer ----------------

        public static string Write(object value)
        {
            var sb = new StringBuilder();
            WriteValue(sb, value, 0);
            return sb.ToString();
        }

        static void Indent(StringBuilder sb, int level) { sb.Append(' ', level * 2); }

        static bool IsScalarArray(List<object> list)
        {
            foreach (object o in list)
                if (o is JObj || o is List<object>) return false;
            return true;
        }

        static void WriteValue(StringBuilder sb, object v, int level)
        {
            if (v == null) { sb.Append("null"); return; }
            if (v is string) { WriteString(sb, (string)v); return; }
            if (v is bool) { sb.Append((bool)v ? "true" : "false"); return; }
            if (v is double || v is float || v is int || v is long)
            {
                double d = Convert.ToDouble(v, CultureInfo.InvariantCulture);
                if (double.IsNaN(d) || double.IsInfinity(d)) sb.Append("null");
                else sb.Append(d.ToString("R", CultureInfo.InvariantCulture));
                return;
            }
            var obj = v as JObj;
            if (obj != null)
            {
                if (obj.Items.Count == 0) { sb.Append("{}"); return; }
                sb.Append("{\n");
                for (int i = 0; i < obj.Items.Count; i++)
                {
                    Indent(sb, level + 1);
                    WriteString(sb, obj.Items[i].Key);
                    sb.Append(": ");
                    WriteValue(sb, obj.Items[i].Value, level + 1);
                    if (i < obj.Items.Count - 1) sb.Append(',');
                    sb.Append('\n');
                }
                Indent(sb, level);
                sb.Append('}');
                return;
            }
            var list = v as List<object>;
            if (list != null)
            {
                if (list.Count == 0) { sb.Append("[]"); return; }
                if (IsScalarArray(list))
                {
                    sb.Append('[');
                    for (int i = 0; i < list.Count; i++)
                    {
                        if (i > 0) sb.Append(", ");
                        WriteValue(sb, list[i], level + 1);
                    }
                    sb.Append(']');
                    return;
                }
                sb.Append("[\n");
                for (int i = 0; i < list.Count; i++)
                {
                    Indent(sb, level + 1);
                    WriteValue(sb, list[i], level + 1);
                    if (i < list.Count - 1) sb.Append(',');
                    sb.Append('\n');
                }
                Indent(sb, level);
                sb.Append(']');
                return;
            }
            throw new ArgumentException("Unsupported JSON value type: " + v.GetType().Name);
        }

        static void WriteString(StringBuilder sb, string s)
        {
            sb.Append('"');
            foreach (char c in s)
            {
                switch (c)
                {
                    case '"': sb.Append("\\\""); break;
                    case '\\': sb.Append("\\\\"); break;
                    case '\n': sb.Append("\\n"); break;
                    case '\r': sb.Append("\\r"); break;
                    case '\t': sb.Append("\\t"); break;
                    default:
                        if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                        else sb.Append(c);
                        break;
                }
            }
            sb.Append('"');
        }

        // ---------------- reader ----------------

        /// <summary>Parses JSON. Returns JObj, List&lt;object&gt;, string, double, bool or null.
        /// Allows // line comments so the config file can be annotated.</summary>
        public static object Parse(string text)
        {
            int pos = 0;
            object v = ParseValue(text, ref pos);
            SkipWs(text, ref pos);
            if (pos < text.Length) throw Error(text, pos, "Unexpected trailing characters");
            return v;
        }

        static FormatException Error(string t, int pos, string msg)
        {
            int line = 1, col = 1;
            for (int i = 0; i < pos && i < t.Length; i++)
            {
                if (t[i] == '\n') { line++; col = 1; } else col++;
            }
            return new FormatException("JSON error at line " + line + ", column " + col + ": " + msg);
        }

        static void SkipWs(string t, ref int pos)
        {
            while (pos < t.Length)
            {
                char c = t[pos];
                if (c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == '\uFEFF') { pos++; continue; }
                if (c == '/' && pos + 1 < t.Length && t[pos + 1] == '/')
                {
                    while (pos < t.Length && t[pos] != '\n') pos++;
                    continue;
                }
                break;
            }
        }

        static object ParseValue(string t, ref int pos)
        {
            SkipWs(t, ref pos);
            if (pos >= t.Length) throw Error(t, pos, "Unexpected end of input");
            char c = t[pos];
            if (c == '{') return ParseObject(t, ref pos);
            if (c == '[') return ParseArray(t, ref pos);
            if (c == '"') return ParseString(t, ref pos);
            if (Match(t, ref pos, "true")) return true;
            if (Match(t, ref pos, "false")) return false;
            if (Match(t, ref pos, "null")) return null;
            return ParseNumber(t, ref pos);
        }

        static bool Match(string t, ref int pos, string word)
        {
            if (string.CompareOrdinal(t, pos, word, 0, word.Length) == 0)
            {
                pos += word.Length;
                return true;
            }
            return false;
        }

        static JObj ParseObject(string t, ref int pos)
        {
            var obj = new JObj();
            pos++; // {
            SkipWs(t, ref pos);
            if (pos < t.Length && t[pos] == '}') { pos++; return obj; }
            while (true)
            {
                SkipWs(t, ref pos);
                if (pos >= t.Length || t[pos] != '"') throw Error(t, pos, "Expected property name in quotes");
                string key = ParseString(t, ref pos);
                SkipWs(t, ref pos);
                if (pos >= t.Length || t[pos] != ':') throw Error(t, pos, "Expected ':' after property name");
                pos++;
                obj.Add(key, ParseValue(t, ref pos));
                SkipWs(t, ref pos);
                if (pos < t.Length && t[pos] == ',')
                {
                    pos++;
                    SkipWs(t, ref pos);
                    if (pos < t.Length && t[pos] == '}') { pos++; return obj; } // tolerate trailing comma
                    continue;
                }
                if (pos < t.Length && t[pos] == '}') { pos++; return obj; }
                throw Error(t, pos, "Expected ',' or '}'");
            }
        }

        static List<object> ParseArray(string t, ref int pos)
        {
            var list = new List<object>();
            pos++; // [
            SkipWs(t, ref pos);
            if (pos < t.Length && t[pos] == ']') { pos++; return list; }
            while (true)
            {
                list.Add(ParseValue(t, ref pos));
                SkipWs(t, ref pos);
                if (pos < t.Length && t[pos] == ',')
                {
                    pos++;
                    SkipWs(t, ref pos);
                    if (pos < t.Length && t[pos] == ']') { pos++; return list; }
                    continue;
                }
                if (pos < t.Length && t[pos] == ']') { pos++; return list; }
                throw Error(t, pos, "Expected ',' or ']'");
            }
        }

        static string ParseString(string t, ref int pos)
        {
            var sb = new StringBuilder();
            pos++; // opening quote
            while (pos < t.Length)
            {
                char c = t[pos++];
                if (c == '"') return sb.ToString();
                if (c != '\\') { sb.Append(c); continue; }
                if (pos >= t.Length) break;
                char e = t[pos++];
                switch (e)
                {
                    case '"': sb.Append('"'); break;
                    case '\\': sb.Append('\\'); break;
                    case '/': sb.Append('/'); break;
                    case 'b': sb.Append('\b'); break;
                    case 'f': sb.Append('\f'); break;
                    case 'n': sb.Append('\n'); break;
                    case 'r': sb.Append('\r'); break;
                    case 't': sb.Append('\t'); break;
                    case 'u':
                        if (pos + 4 > t.Length) throw Error(t, pos, "Bad \\u escape");
                        sb.Append((char)int.Parse(t.Substring(pos, 4), NumberStyles.HexNumber, CultureInfo.InvariantCulture));
                        pos += 4;
                        break;
                    default:
                        // Be forgiving with Windows paths typed as "C:\Laser DXF\" - keep the backslash.
                        sb.Append('\\').Append(e);
                        break;
                }
            }
            throw Error(t, pos, "Unterminated string");
        }

        static double ParseNumber(string t, ref int pos)
        {
            int start = pos;
            while (pos < t.Length && "+-0123456789.eE".IndexOf(t[pos]) >= 0) pos++;
            double d;
            if (pos == start || !double.TryParse(t.Substring(start, pos - start), NumberStyles.Float, CultureInfo.InvariantCulture, out d))
                throw Error(t, start, "Invalid value");
            return d;
        }
    }
}

// ----- core/PlateAnalyzer.cs -----
// Turns a BodyModel + selected planar face into: outward normal, thickness,
// a right-handed 2D frame, the outer loop, inner loops and per-hole analysis.
namespace LaserDxf.Core
{
    using System;
    using System.Collections.Generic;

    public class PlateException : Exception
    {
        public PlateException(string message) : base(message) { }
    }

    public sealed class OrientedEdge
    {
        public int EdgeId;
        public bool Reversed;
    }

    public sealed class FaceLoop
    {
        public List<OrientedEdge> Edges = new List<OrientedEdge>();
        /// <summary>Closed polyline through the edge samples (last point not repeated).</summary>
        public List<Vec3> Points = new List<Vec3>();
        public bool Closed = true;
        /// <summary>Signed area relative to the outward plate normal.</summary>
        public double Area;
        public bool IsOuter;
    }

    public sealed class HoleInfo
    {
        public int Index;
        public FaceLoop Loop;
        public bool IsCircle;
        public Vec3 Center;
        public Vec2 Center2;
        /// <summary>Diameter of the loop on the selected face.</summary>
        public double TopDiameter = double.NaN;
        /// <summary>Narrowest coaxial circular edge through the plate (the laser-cut bore).</summary>
        public double MinDiameter = double.NaN;
        public bool Through;
        public bool HasCone;
        /// <summary>A conical face meets the selected face (countersink opens on this side).</summary>
        public bool ConeAtSurface;
        /// <summary>A planar floor/step parallel to the face part-way through (counterbore or pocket).</summary>
        public bool HasStep;
        public List<int> WallFaceIds = new List<int>();
        public List<int> FeatureIds = new List<int>();
        public string WallSummary = "";
        public Bounds2 Bounds;
    }

    public enum XAlignMode { LongestEdge, Hint }

    public sealed class AnalysisOptions
    {
        /// <summary>Geometric tolerance in mm.</summary>
        public double Tol = 0.01;
        public XAlignMode XAlign = XAlignMode.LongestEdge;
        /// <summary>Used for XAlign = Hint (e.g. WCS X) and as fallback when there is no straight edge.</summary>
        public Vec3 XHint = Vec3.UnitX;
    }

    public sealed class FaceAnalysis
    {
        public int FaceId;
        public Vec3 Normal;
        public double Thickness;
        public PlateFrame Frame;
        public FaceLoop Outer;
        public List<FaceLoop> Inner = new List<FaceLoop>();
        public List<HoleInfo> Holes = new List<HoleInfo>();
        public int LongestEdgeId = -1;
        /// <summary>Outer profile bounds in frame coordinates (MinX = MinY = 0).</summary>
        public Bounds2 Bounds;
        public double NetArea;
        public List<string> Warnings = new List<string>();
    }

    /// <summary>An edge mapped onto the plate plane as a true arc (CCW from StartDeg to EndDeg).</summary>
    public sealed class Arc2
    {
        public Vec2 Center;
        public double Radius;
        public double StartDeg;
        public double EndDeg;
        public bool Full;
    }

    public static class EdgeGeom2
    {
        static double NormDeg(double a)
        {
            a %= 360.0;
            if (a < 0) a += 360.0;
            return a;
        }

        static double AngleDeg(Vec2 c, Vec2 p)
        {
            return NormDeg(Math.Atan2(p.Y - c.Y, p.X - c.X) * 180.0 / Math.PI);
        }

        /// <summary>True if the edge is a circle/arc whose axis is normal to the plate.</summary>
        public static bool TryArc(TopoEdge e, PlateFrame fr, double tol, out Arc2 arc)
        {
            arc = null;
            if (!e.HasCircle || Math.Abs(e.Axis.Dot(fr.ZAxis)) < 0.9999 || e.Points.Count < 3) return false;
            var a = new Arc2 { Center = fr.ToLocal(e.Center), Radius = e.Radius };
            if (e.IsClosed(tol))
            {
                a.Full = true;
                a.StartDeg = 0;
                a.EndDeg = 360;
                arc = a;
                return true;
            }
            double a0 = AngleDeg(a.Center, fr.ToLocal(e.Start));
            double a1 = AngleDeg(a.Center, fr.ToLocal(e.End));
            double am = AngleDeg(a.Center, fr.ToLocal(e.Points[e.Points.Count / 2]));
            double sweep = NormDeg(a1 - a0);
            if (sweep == 0) sweep = 360;
            if (NormDeg(am - a0) < sweep)
            {
                a.StartDeg = a0;
                a.EndDeg = a1;
            }
            else
            {
                a.StartDeg = a1;
                a.EndDeg = a0;
            }
            arc = a;
            return true;
        }

        public static bool AngleInCcwRange(double ang, double start, double end)
        {
            double s = NormDeg(end - start);
            if (s == 0) s = 360;
            return NormDeg(ang - start) <= s;
        }

        /// <summary>Grows b by the exact 2D extent of the edge (arcs include their quadrant points).</summary>
        public static void AddBounds(TopoEdge e, PlateFrame fr, double tol, ref Bounds2 b)
        {
            foreach (var p in e.Points) b.Add(fr.ToLocal(p));
            Arc2 arc;
            if (!TryArc(e, fr, tol, out arc)) return;
            for (int k = 0; k < 4; k++)
            {
                double ang = k * 90.0;
                if (arc.Full || AngleInCcwRange(ang, arc.StartDeg, arc.EndDeg))
                {
                    double r = ang * Math.PI / 180.0;
                    b.Add(new Vec2(arc.Center.X + arc.Radius * Math.Cos(r), arc.Center.Y + arc.Radius * Math.Sin(r)));
                }
            }
        }
    }

    public static class PlateAnalyzer
    {
        // ---------------- loops ----------------

        public static List<FaceLoop> BuildLoops(BodyModel m, TopoFace face, double tol, List<string> warnings)
        {
            var loops = new List<FaceLoop>();
            var remaining = new List<TopoEdge>();
            foreach (int id in face.EdgeIds)
            {
                TopoEdge e = m.Edge(id);
                if (e.Points.Count < 2) continue;
                if (e.IsClosed(tol))
                {
                    var single = new FaceLoop();
                    single.Edges.Add(new OrientedEdge { EdgeId = e.Id });
                    loops.Add(single);
                }
                else remaining.Add(e);
            }

            while (remaining.Count > 0)
            {
                var loop = new FaceLoop();
                TopoEdge first = remaining[0];
                remaining.RemoveAt(0);
                loop.Edges.Add(new OrientedEdge { EdgeId = first.Id });
                Vec3 loopStart = first.Start;
                Vec3 cur = first.End;
                while (cur.DistanceTo(loopStart) > tol)
                {
                    int bestIdx = -1;
                    bool bestRev = false;
                    double bestDist = tol;
                    for (int i = 0; i < remaining.Count; i++)
                    {
                        double ds = remaining[i].Start.DistanceTo(cur);
                        double de = remaining[i].End.DistanceTo(cur);
                        if (ds <= bestDist) { bestDist = ds; bestIdx = i; bestRev = false; }
                        if (de <= bestDist) { bestDist = de; bestIdx = i; bestRev = true; }
                    }
                    if (bestIdx < 0)
                    {
                        loop.Closed = false;
                        if (warnings != null)
                            warnings.Add("Face " + face.Id + ": a loop does not close (gap at " + cur + "). Its outline may be incomplete.");
                        break;
                    }
                    TopoEdge next = remaining[bestIdx];
                    remaining.RemoveAt(bestIdx);
                    loop.Edges.Add(new OrientedEdge { EdgeId = next.Id, Reversed = bestRev });
                    cur = bestRev ? next.Start : next.End;
                }
                loops.Add(loop);
            }

            foreach (var loop in loops) FillPoints(m, loop);
            return loops;
        }

        static void FillPoints(BodyModel m, FaceLoop loop)
        {
            loop.Points.Clear();
            foreach (var oe in loop.Edges)
            {
                List<Vec3> pts = EdgePolyline(m.Edge(oe.EdgeId));
                int n = pts.Count;
                // Skip each edge's last point: the next edge starts there (or the loop closes).
                for (int i = 0; i < n - 1; i++)
                    loop.Points.Add(oe.Reversed ? pts[n - 1 - i] : pts[i]);
            }
        }

        /// <summary>Edge as a polyline; arcs are densified (5 degree steps) so loop areas are accurate.</summary>
        public static List<Vec3> EdgePolyline(TopoEdge e)
        {
            if (!e.HasCircle || e.Radius <= 0) return e.Points;
            // Axis comes from a 3-point fit in traversal order, so the edge runs CCW about it.
            Vec3 u = (e.Start - e.Center).Normalized();
            Vec3 v = e.Axis.Cross(u);
            double sweep = 2 * Math.PI;
            if (e.Start.DistanceTo(e.End) > 1e-9 * Math.Max(1, e.Radius))
            {
                Vec3 d = e.End - e.Center;
                sweep = Math.Atan2(d.Dot(v), d.Dot(u));
                if (sweep <= 0) sweep += 2 * Math.PI;
            }
            int n = Math.Max(4, (int)Math.Ceiling(sweep / (Math.PI / 36)));
            var pts = new List<Vec3>(n + 1);
            for (int i = 0; i < n; i++)
            {
                double t = sweep * i / n;
                pts.Add(e.Center + (u * Math.Cos(t) + v * Math.Sin(t)) * e.Radius);
            }
            pts.Add(e.End);
            return pts;
        }

        // ---------------- face analysis ----------------

        public static FaceAnalysis Analyze(BodyModel m, int faceId, AnalysisOptions opt)
        {
            TopoFace face = m.Face(faceId);
            if (face.Kind != FaceKind.Planar)
                throw new PlateException("The selected face is not planar (NX face type: " + face.NxType + "). Select the flat top or bottom face of the plate.");

            var a = new FaceAnalysis { FaceId = faceId };
            List<FaceLoop> loops = BuildLoops(m, face, opt.Tol, a.Warnings);
            if (loops.Count == 0) throw new PlateException("The selected face has no edges.");

            // Plane normal from the biggest loop (that is the outer loop on a planar face).
            FaceLoop outer = null;
            Vec3 best = Vec3.Zero;
            foreach (var l in loops)
            {
                Vec3 nn = GeomUtil.NewellNormal(l.Points);
                if (nn.Length > best.Length) { best = nn; outer = l; }
            }
            if (outer == null || best.Length < 1e-9) throw new PlateException("Could not work out the plane of the selected face.");

            Vec3 n = best.Normalized();
            Vec3 p0 = outer.Points[0];

            // Outward normal: the body's material must sit behind the face.
            double maxD = 0, minD = 0;
            foreach (var p in m.AllPoints())
            {
                double d = (p - p0).Dot(n);
                if (d > maxD) maxD = d;
                if (d < minD) minD = d;
            }
            if (maxD > -minD)
            {
                n = -n;
                double t = maxD;
                maxD = -minD;
                minD = -t;
            }
            a.Normal = n;
            a.Thickness = -minD;
            if (a.Thickness < opt.Tol) throw new PlateException("The body has no measurable thickness behind the selected face.");
            if (maxD > Math.Max(opt.Tol * 5, 0.05))
                a.Warnings.Add("Some of the body lies " + Fmt.N(maxD, 3) + " mm in front of the selected face. Is it really the top or bottom face of a flat plate?");

            foreach (var l in loops) l.Area = GeomUtil.NewellNormal(l.Points).Dot(n) * 0.5;
            outer.IsOuter = true;
            a.Outer = outer;
            foreach (var l in loops) if (l != outer) a.Inner.Add(l);

            a.Frame = BuildFrame(m, a, p0, opt);

            a.NetArea = Math.Abs(outer.Area);
            foreach (var l in a.Inner) a.NetArea -= Math.Abs(l.Area);

            int index = 1;
            foreach (var l in a.Inner)
            {
                HoleInfo h = AnalyzeHole(m, face, l, a.Frame, a.Thickness, opt.Tol);
                h.Index = index++;
                a.Holes.Add(h);
            }
            return a;
        }

        static PlateFrame BuildFrame(BodyModel m, FaceAnalysis a, Vec3 p0, AnalysisOptions opt)
        {
            Vec3 n = a.Normal;
            Vec3 x = Vec3.Zero;
            Vec3 edgePoint = p0;

            if (opt.XAlign == XAlignMode.LongestEdge)
            {
                double bestLen = 0;
                foreach (var oe in a.Outer.Edges)
                {
                    TopoEdge e = m.Edge(oe.EdgeId);
                    if (e.Kind != EdgeKind.Line) continue;
                    Vec3 v = GeomUtil.ProjectOntoPlane(e.End - e.Start, n);
                    if (v.Length > bestLen + opt.Tol)
                    {
                        bestLen = v.Length;
                        x = v;
                        edgePoint = e.Start;
                        a.LongestEdgeId = e.Id;
                    }
                }
                if (a.LongestEdgeId < 0)
                    a.Warnings.Add("The outer profile has no straight edge, so X follows the fallback direction (WCS X).");
            }

            if (x.Length < opt.Tol)
            {
                x = GeomUtil.ProjectOntoPlane(opt.XHint, n);
                if (x.Length < 1e-6) x = GeomUtil.ProjectOntoPlane(Vec3.UnitX, n);
                if (x.Length < 1e-6) x = GeomUtil.ProjectOntoPlane(Vec3.UnitY, n);
            }
            x = x.Normalized();

            var fr = new PlateFrame { Origin = p0, XAxis = x, YAxis = n.Cross(x), ZAxis = n };

            // Longest edge goes along the bottom: the plate must lie above it.
            if (a.LongestEdgeId >= 0)
            {
                Bounds2 b0 = OuterBounds(m, a.Outer, fr, opt.Tol);
                double centreY = (b0.MinY + b0.MaxY) * 0.5;
                if (centreY < fr.ToLocal(edgePoint).Y)
                {
                    fr.XAxis = -fr.XAxis;
                    fr.YAxis = -fr.YAxis; // rotate 180 degrees about Z - never a mirror
                }
            }

            // Origin at the bottom-left of the outer profile's bounding box.
            Bounds2 b = OuterBounds(m, a.Outer, fr, opt.Tol);
            fr.Origin = fr.Origin + fr.XAxis * b.MinX + fr.YAxis * b.MinY;
            a.Bounds = OuterBounds(m, a.Outer, fr, opt.Tol);
            return fr;
        }

        public static Bounds2 OuterBounds(BodyModel m, FaceLoop loop, PlateFrame fr, double tol)
        {
            Bounds2 b = Bounds2.Empty;
            foreach (var oe in loop.Edges) EdgeGeom2.AddBounds(m.Edge(oe.EdgeId), fr, tol, ref b);
            return b;
        }

        // ---------------- holes ----------------

        static HoleInfo AnalyzeHole(BodyModel m, TopoFace top, FaceLoop loop, PlateFrame fr, double thickness, double tol)
        {
            var h = new HoleInfo { Loop = loop };
            double depthTol = Math.Max(tol * 5, 0.02);

            // Is the loop one circle (possibly split into several arcs)?
            bool allCirc = loop.Closed;
            TopoEdge firstEdge = m.Edge(loop.Edges[0].EdgeId);
            foreach (var oe in loop.Edges)
            {
                TopoEdge e = m.Edge(oe.EdgeId);
                if (!e.HasCircle || e.Center.DistanceTo(firstEdge.Center) > tol || Math.Abs(e.Radius - firstEdge.Radius) > tol)
                {
                    allCirc = false;
                    break;
                }
            }
            h.IsCircle = allCirc;
            if (allCirc)
            {
                h.Center = firstEdge.Center;
                h.Center2 = fr.ToLocal(firstEdge.Center);
                h.TopDiameter = 2 * firstEdge.Radius;
            }
            Bounds2 bb = Bounds2.Empty;
            foreach (var oe in loop.Edges) EdgeGeom2.AddBounds(m.Edge(oe.EdgeId), fr, tol, ref bb);
            h.Bounds = bb;
            if (!allCirc) h.Center2 = new Vec2((bb.MinX + bb.MaxX) * 0.5, (bb.MinY + bb.MaxY) * 0.5);

            // Flood-fill the hole's wall faces from the loop, stopping at the far face of the plate.
            var visited = new IntSet();
            visited.Add(top.Id);
            var queue = new Queue<int>();
            foreach (var oe in loop.Edges)
            {
                foreach (int fid in m.Edge(oe.EdgeId).FaceIds)
                {
                    if (visited.Add(fid))
                    {
                        queue.Enqueue(fid);
                        if (m.Face(fid).Kind == FaceKind.Conical) h.ConeAtSurface = true;
                    }
                }
            }

            var kinds = new List<string>();
            while (queue.Count > 0)
            {
                TopoFace g = m.Face(queue.Dequeue());
                double dmin = double.MaxValue, dmax = double.MinValue;
                foreach (int eid in g.EdgeIds)
                {
                    foreach (var p in m.Edge(eid).Points)
                    {
                        double d = -fr.Height(p);
                        if (d < dmin) dmin = d;
                        if (d > dmax) dmax = d;
                    }
                }
                bool parallelPlanar = g.Kind == FaceKind.Planar && dmax - dmin <= depthTol;
                if (parallelPlanar)
                {
                    double d = (dmin + dmax) * 0.5;
                    if (Math.Abs(d - thickness) <= depthTol) { h.Through = true; continue; }
                    if (d <= depthTol) continue; // another face level with the top - not part of this hole
                    h.HasStep = true;
                }
                h.WallFaceIds.Add(g.Id);
                if (g.Kind == FaceKind.Conical) h.HasCone = true;
                string k = parallelPlanar ? "Floor" : g.Kind.ToString();
                if (!kinds.Contains(k)) kinds.Add(k);

                if (h.WallFaceIds.Count > 500) break; // runaway guard
                foreach (int eid in g.EdgeIds)
                    foreach (int nf in m.Edge(eid).FaceIds)
                        if (visited.Add(nf)) queue.Enqueue(nf);
            }
            h.WallSummary = string.Join("+", kinds.ToArray());

            // Narrowest coaxial circle anywhere in the walls = the bore the laser must cut.
            var edgeIds = new IntSet();
            foreach (var oe in loop.Edges) edgeIds.Add(oe.EdgeId);
            foreach (int fid in h.WallFaceIds) foreach (int eid in m.Face(fid).EdgeIds) edgeIds.Add(eid);
            foreach (int eid in edgeIds.Items)
            {
                TopoEdge e = m.Edge(eid);
                if (!e.HasCircle || Math.Abs(e.Axis.Dot(fr.ZAxis)) < 0.9999) continue;
                if (h.IsCircle && fr.ToLocal(e.Center).DistanceTo(h.Center2) > tol * 10) continue;
                double dia = 2 * e.Radius;
                if (double.IsNaN(h.MinDiameter) || dia < h.MinDiameter) h.MinDiameter = dia;
            }

            var wallSet = new IntSet();
            foreach (int fid in h.WallFaceIds) wallSet.Add(fid);
            foreach (var f in m.Features)
            {
                foreach (int fid in f.FaceIds)
                {
                    if (wallSet.Contains(fid)) { h.FeatureIds.Add(f.Id); break; }
                }
            }
            return h;
        }

        // ---------------- body selection ----------------

        /// <summary>Largest planar face by outer-profile area. When the two plate faces tie (within 2%),
        /// prefer the face that countersinks open onto, then the one facing preferredUp.</summary>
        public static int PickPlateFace(BodyModel m, AnalysisOptions opt, Vec3 preferredUp, List<string> log)
        {
            var cands = new List<KeyValuePair<int, double>>();
            foreach (var f in m.Faces)
            {
                if (f.Kind != FaceKind.Planar) continue;
                List<FaceLoop> loops = BuildLoops(m, f, opt.Tol, null);
                double outer = 0;
                foreach (var l in loops) outer = Math.Max(outer, GeomUtil.NewellNormal(l.Points).Length * 0.5);
                cands.Add(new KeyValuePair<int, double>(f.Id, outer));
            }
            if (cands.Count == 0) throw new PlateException("The selected body has no planar faces.");
            cands.Sort((p, q) => q.Value.CompareTo(p.Value));

            int pick = cands[0].Key;
            if (cands.Count > 1 && cands[1].Value >= cands[0].Value * 0.98)
            {
                FaceAnalysis a0 = Analyze(m, cands[0].Key, opt);
                FaceAnalysis a1 = Analyze(m, cands[1].Key, opt);
                int cs0 = 0, cs1 = 0;
                foreach (var h in a0.Holes) if (h.ConeAtSurface) cs0++;
                foreach (var h in a1.Holes) if (h.ConeAtSurface) cs1++;
                if (cs0 != cs1)
                {
                    pick = cs0 > cs1 ? a0.FaceId : a1.FaceId;
                    if (log != null) log.Add("Two plate faces of equal size: picked face " + pick + " because the countersinks open onto it.");
                }
                else
                {
                    pick = a0.Normal.Dot(preferredUp) >= a1.Normal.Dot(preferredUp) ? a0.FaceId : a1.FaceId;
                    if (log != null) log.Add("Two plate faces of equal size: picked face " + pick + " (the one facing up).");
                }
            }
            else if (log != null) log.Add("Picked the largest planar face: face " + pick + ".");
            return pick;
        }
    }
}

// ----- core/ProbeReport.cs -----
// Human-readable report of a face analysis (step 1 probe). Pure text, no NX.
namespace LaserDxf.Core
{
    using System;
    using System.Collections.Generic;
    using System.Text;

    public static class ProbeReport
    {
        static string Pad(string s, int w) { return s.Length >= w ? s : s + new string(' ', w - s.Length); }
        static string PadL(string s, int w) { return s.Length >= w ? s : new string(' ', w - s.Length) + s; }

        public static List<string> Summary(BodyModel m, FaceAnalysis a, string selectionNote)
        {
            var L = new List<string>();
            PlateFrame fr = a.Frame;
            L.Add("Part         : " + m.PartName + "   (units: " + m.Units + ")");
            L.Add("Face         : #" + a.FaceId + "  " + selectionNote);
            L.Add("Normal (out) : " + a.Normal);
            L.Add("Thickness    : " + Fmt.N(a.Thickness, 3) + " mm");
            L.Add("Plate size   : " + Fmt.N(a.Bounds.Width, 2) + " x " + Fmt.N(a.Bounds.Height, 2) + " mm (DXF X x Y)");
            if (a.LongestEdgeId >= 0)
                L.Add("X axis       : along edge #" + a.LongestEdgeId + " (longest straight edge, " + Fmt.N(m.Edge(a.LongestEdgeId).Length, 2) + " mm), plate above it");
            else
                L.Add("X axis       : fallback direction");
            L.Add("Frame        : origin " + fr.Origin + "  X " + fr.XAxis + "  Y " + fr.YAxis + "  Z " + fr.ZAxis + "  handedness " + Fmt.N(fr.Handedness, 3));

            int lines = 0, arcs = 0, other = 0;
            foreach (var oe in a.Outer.Edges)
            {
                TopoEdge e = m.Edge(oe.EdgeId);
                if (e.Kind == EdgeKind.Line) lines++;
                else if (e.HasCircle) arcs++;
                else other++;
            }
            L.Add("Outer loop   : " + a.Outer.Edges.Count + " edges (" + lines + " lines, " + arcs + " arcs, " + other + " other), " +
                  "net plate area " + Fmt.N(a.NetArea, 1) + " mm2" + (a.Outer.Closed ? "" : "  ** NOT CLOSED **"));

            int circ = 0, through = 0;
            foreach (var h in a.Holes)
            {
                if (h.IsCircle) circ++;
                if (h.Through) through++;
            }
            L.Add("Inner loops  : " + a.Holes.Count + " (" + circ + " circular, " + (a.Holes.Count - circ) + " other; " +
                  through + " go right through, " + (a.Holes.Count - through) + " do not)");

            L.Add("");
            L.Add("Holes  (centre in DXF coordinates; dia at face / narrowest dia through the plate)");
            L.Add("   #  " + Pad("centre x, y", 22) + PadL("dia face", 9) + PadL("dia bore", 9) + "  through  " + Pad("walls", 28) + "features");
            foreach (var h in a.Holes)
            {
                var feats = new List<string>();
                foreach (int fid in h.FeatureIds)
                {
                    foreach (var f in m.Features)
                        if (f.Id == fid) feats.Add(f.Name);
                }
                string centre = Fmt.N(h.Center2.X, 3) + ", " + Fmt.N(h.Center2.Y, 3);
                string kind = h.IsCircle ? "" : "  [non-circular " + Fmt.N(h.Bounds.Width, 2) + " x " + Fmt.N(h.Bounds.Height, 2) + "]";
                string flags = (h.ConeAtSurface ? " CS-this-side" : "") + (h.HasStep ? " step" : "");
                L.Add(PadL(h.Index.ToString(), 4) + "  " + Pad(centre, 22) +
                      PadL(double.IsNaN(h.TopDiameter) ? "-" : Fmt.N(h.TopDiameter, 3), 9) +
                      PadL(double.IsNaN(h.MinDiameter) ? "-" : Fmt.N(h.MinDiameter, 3), 9) + "  " +
                      Pad(h.Through ? "yes" : "NO", 7) + "  " + Pad(h.WallSummary + flags, 28) +
                      string.Join(", ", feats.ToArray()) + kind);
            }

            // Group by bore diameter - this is what the label lookup table will key on.
            var groups = new SortedDictionary<double, int>();
            foreach (var h in a.Holes)
            {
                if (!h.IsCircle || double.IsNaN(h.MinDiameter)) continue;
                double key = Math.Round(h.MinDiameter, 3);
                int c;
                groups.TryGetValue(key, out c);
                groups[key] = c + 1;
            }
            if (groups.Count > 0)
            {
                L.Add("");
                var parts = new List<string>();
                foreach (var kv in groups) parts.Add("dia " + Fmt.N(kv.Key, 3) + " x" + kv.Value);
                L.Add("Bore diameters: " + string.Join(";  ", parts.ToArray()));
            }
            return L;
        }

        public static List<string> FaceEdges(BodyModel m, FaceAnalysis a)
        {
            var L = new List<string>();
            PlateFrame fr = a.Frame;
            L.Add("Edges of the selected face (DXF coordinates):");
            L.Add("  loop   edge  " + Pad("NX type", 14) + PadL("length", 10) + "  " + Pad("start", 24) + Pad("end", 24) + "circle");
            var loops = new List<FaceLoop> { a.Outer };
            loops.AddRange(a.Inner);
            for (int li = 0; li < loops.Count; li++)
            {
                string loopName = li == 0 ? "outer" : "in" + li;
                foreach (var oe in loops[li].Edges)
                {
                    TopoEdge e = m.Edge(oe.EdgeId);
                    Vec2 s = fr.ToLocal(oe.Reversed ? e.End : e.Start);
                    Vec2 en = fr.ToLocal(oe.Reversed ? e.Start : e.End);
                    string circle = "";
                    Arc2 arc;
                    if (EdgeGeom2.TryArc(e, fr, 0.01, out arc))
                        circle = "c " + arc.Center + " r " + Fmt.N(arc.Radius, 4) + (arc.Full ? " full" : " " + Fmt.N(arc.StartDeg, 2) + "->" + Fmt.N(arc.EndDeg, 2) + " deg");
                    else if (e.HasCircle) circle = "circle not parallel to face";
                    else if (e.Kind == EdgeKind.Other) circle = e.Points.Count + " samples";
                    L.Add("  " + Pad(loopName, 6) + PadL(e.Id.ToString(), 5) + "  " + Pad(e.NxType, 14) + PadL(Fmt.N(e.Length, 3), 10) + "  " +
                          Pad(s.ToString(), 24) + Pad(en.ToString(), 24) + circle);
                }
            }
            return L;
        }

        public static List<string> Features(BodyModel m, bool withProps)
        {
            var L = new List<string>();
            L.Add("Features on the body: " + m.Features.Count);
            foreach (var f in m.Features)
            {
                L.Add("  [" + f.Id + "] " + f.Name + "  type=" + f.FeatureType + "  class=" + f.ClassName + "  faces=" + f.FaceIds.Count);
                if (!withProps) continue;
                foreach (var kv in f.Props) L.Add("        " + kv.Key + " = " + kv.Value);
            }
            return L;
        }

        public static List<string> Attributes(BodyModel m)
        {
            var L = new List<string>();
            L.Add("Part attributes: " + m.Attributes.Count + "   (category | title | alias = value  [type])");
            foreach (var a in m.Attributes)
            {
                L.Add("  " + Pad(a.Category, 34) + " | " + Pad(a.Title, 28) + " | " + Pad(a.Alias, 18) + " = " +
                      (a.IsSet ? "\"" + a.Value + "\"" : "<unset>") + "  [" + a.Type + "]");
            }
            return L;
        }

        public static string Join(List<string> lines)
        {
            var sb = new StringBuilder();
            foreach (var l in lines) sb.Append(l).Append("\r\n");
            return sb.ToString();
        }
    }
}

// ----- core/Sampler.cs -----
// Adaptive curve sampling used for edges that are neither lines nor arcs.
namespace LaserDxf.Core
{
    using System;
    using System.Collections.Generic;

    public static class Sampler
    {
        /// <summary>Samples eval(t), t in [0,1], so that no chord deviates from the curve's
        /// midpoint by more than tol. Start and end points are always included.</summary>
        public static List<Vec3> Sample(Func<double, Vec3> eval, double tol, int initialSegments, int maxDepth)
        {
            var pts = new List<Vec3>();
            if (initialSegments < 1) initialSegments = 1;
            Vec3 prev = eval(0.0);
            pts.Add(prev);
            for (int i = 1; i <= initialSegments; i++)
            {
                double t0 = (double)(i - 1) / initialSegments;
                double t1 = (double)i / initialSegments;
                Vec3 p1 = eval(t1);
                Refine(eval, t0, prev, t1, p1, tol, maxDepth, pts);
                pts.Add(p1);
                prev = p1;
            }
            return pts;
        }

        static void Refine(Func<double, Vec3> eval, double t0, Vec3 p0, double t1, Vec3 p1, double tol, int depth, List<Vec3> pts)
        {
            if (depth <= 0) return;
            double tm = (t0 + t1) * 0.5;
            Vec3 pm = eval(tm);
            double dev = p0.DistanceTo(p1) < 1e-12 ? pm.DistanceTo(p0) : GeomUtil.DistanceToLine(pm, p0, p1);
            // Also check the quarter points so an S-bend whose midpoint lies on the chord is not missed.
            if (dev <= tol)
            {
                Vec3 pq = eval((t0 + tm) * 0.5);
                Vec3 pr = eval((tm + t1) * 0.5);
                if (GeomUtil.DistanceToLine(pq, p0, p1) <= tol && GeomUtil.DistanceToLine(pr, p0, p1) <= tol) return;
            }
            Refine(eval, t0, p0, tm, pm, tol, depth - 1, pts);
            pts.Add(pm);
            Refine(eval, tm, pm, t1, p1, tol, depth - 1, pts);
        }
    }
}
